import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:path/path.dart' as p;
import 'package:yaml/yaml.dart';

import 'detail/project_assets.dart';

/// Keys looked up in pubspec.yaml and flutter_launcher_icons config files,
/// in priority order
const _pubspecIconKeys = [
  ['sidekick', 'icon'],
  ['flutter_launcher_icons', 'image_path'],
];

/// Launcher icons generated by `flutter create`, relative to the project
const _platformIconPaths = [
  'ios/Runner/Assets.xcassets/AppIcon.appiconset/Icon-App-1024x1024@1x.png',
  'macos/Runner/Assets.xcassets/AppIcon.appiconset/app_icon_1024.png',
  'android/app/src/main/res/mipmap-xxxhdpi/ic_launcher.png',
  'web/icons/Icon-512.png',
  'web/icons/Icon-192.png',
];

/// Max number of entries inspected when looking for a logo in `assets`
const _maxAssetEntries = 2000;

final _launcherIconsConfigPattern =
    RegExp(r'^flutter_launcher_icons(-.*)?\.yaml$');

/// Finds the image that best represents the project at [projectPath].
///
/// Looks, in order, at:
/// 1. `sidekick.icon` and `flutter_launcher_icons.image_path` in pubspec.yaml
/// 2. `flutter_launcher_icons.yaml` / `flutter_launcher_icons-<flavor>.yaml`
///    at the project root
/// 3. an image with "logo" in its name inside `assets`
/// 4. the launcher icons of the platform folders
///
/// Only specific files and the `assets` folder are read, so this stays fast
/// for large projects (it used to list the whole project recursively,
/// including `build` and plugin symlinks, which made refresh very slow).
Future<File?> findProjectIcon(String projectPath) async {
  final configFiles = <File>[
    File(p.join(projectPath, 'pubspec.yaml')),
    ...await _launcherIconsConfigs(projectPath),
  ];

  for (final keys in _pubspecIconKeys) {
    for (final config in configFiles) {
      final value = await _readYamlString(config, keys);
      if (value == null) continue;
      final file = File(p.join(projectPath, value));
      if (isPreviewableImage(file.path) && await file.exists()) return file;
    }
  }

  final logo = await _findAssetsLogo(p.join(projectPath, 'assets'));
  if (logo != null) return logo;

  for (final relative in _platformIconPaths) {
    final file = File(p.joinAll([projectPath, ...relative.split('/')]));
    if (await file.exists()) return file;
  }

  return null;
}

Future<List<File>> _launcherIconsConfigs(String projectPath) async {
  final files = <File>[];
  try {
    await for (final entity
        in Directory(projectPath).list(followLinks: false)) {
      if (entity is File &&
          _launcherIconsConfigPattern.hasMatch(p.basename(entity.path))) {
        files.add(entity);
      }
    }
  } on FileSystemException {
    return files;
  }
  // Put the default config before flavor configs
  files.sort((a, b) => a.path.length.compareTo(b.path.length));
  return files;
}

Future<String?> _readYamlString(File file, List<String> keys) async {
  try {
    if (!await file.exists()) return null;
    dynamic node = loadYaml(await file.readAsString());
    for (final key in keys) {
      if (node is! YamlMap || !node.containsKey(key)) return null;
      node = node[key];
    }
    return node is String && node.isNotEmpty ? node : null;
  } catch (e) {
    debugPrint('Could not read ${file.path}: $e');
    return null;
  }
}

Future<File?> _findAssetsLogo(String assetsPath) async {
  final directory = Directory(assetsPath);
  if (!await directory.exists()) return null;

  final logos = <File>[];
  var inspected = 0;
  try {
    await for (final entity
        in directory.list(recursive: true, followLinks: false)) {
      if (++inspected > _maxAssetEntries) break;
      if (entity is! File) continue;
      final name = p.basename(entity.path).toLowerCase();
      if (isPreviewableImage(name) && name.contains('logo')) logos.add(entity);
    }
  } on FileSystemException catch (e) {
    debugPrint('Could not list $assetsPath: $e');
  }
  if (logos.isEmpty) return null;
  // Prefer the shallowest match, which is the 1x variant
  logos.sort((a, b) => a.path.length.compareTo(b.path.length));
  return logos.first;
}

